\set ON_ERROR_STOP on
begin;
-- Правила ДМС СОГАЗ действующих редакций (по реестру правил страховой).
-- 143 — общие правила ДМС; 003 — правила ДМС граждан. Тексты близки, поэтому правила
-- заводим на каждый документ отдельно: полис живёт по редакции, указанной в договоре.

delete from coverage_rule where document_id in (
  select id from program_document where storage_path in
    ('programs/sogaz_143_dms_2023.pdf','programs/sogaz_003_dms_grazhdan_2023.pdf'));

-- ── 143_Правила ДМС (ред. 01.02.2023) ──
with d as (select id, insurance_company_id from program_document where storage_path='programs/sogaz_143_dms_2023.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховой случай обращение в медорганизацию по программе','conditional','страховым случаем является обращение застрахованного в организацию из числа предусмотренных договором за услугами, входящими в программу страхования','п. 1.3; п. 3.1'),
('общие-условия','перечень услуг вне покрытия определяется договором','conditional','перечень услуг и заболеваний, обращение по которым не является страховым случаем, указывается в договоре страхования и программе','п. 3.4 – 3.5'),
('общие-исключения','любая форма опьянения наркотические психотропные препараты без назначения врача','excluded',null,'п. 4.1.1'),
('общие-исключения','умышленные противоправные действия','excluded',null,'п. 4.1.2'),
('общие-исключения','покушение на самоубийство умышленное причинение себе телесных повреждений','excluded','кроме случаев доведения противоправными действиями третьих лиц','п. 4.1.3'),
('общие-исключения','террористический акт диверсия','excluded',null,'п. 4.1.4'),
('общие-исключения','заболевания представляющие опасность для окружающих оспа чума холера covid-19','excluded','договором может быть предусмотрено неприменение этого исключения полностью или частично','п. 4.1.5'),
('общие-условия','услуги невозможны из-за ограничительных мероприятий карантина','excluded','режим повышенной готовности, санитарно-противоэпидемические мероприятия','п. 4.1.6'),
('общие-условия','исключения могут быть сняты договором','conditional','договором страхования может быть предусмотрено неприменение исключений п. 4.1.1 – 4.1.5 полностью или частично','п. 4.2'),
('общие-условия','изменение и дополнение положений правил договором','conditional','стороны вправе договориться об изменении, дополнении или исключении отдельных положений Правил','п. 4.4'),
('лекарства','лекарственная помощь','conditional','оплачивается, если предусмотрена программой страхования по договору','п. 2.1.2'),
('общие-условия','иные услуги сервисные','conditional','состав иных услуг определяется программой страхования','п. 2.1.3'),
('общие-условия','услуги в организациях по соглашению сторон','conditional','медицинские организации могут быть согласованы сторонами дополнительно к перечисленным в договоре','п. 1.5'),
('общие-условия','условия страхования по отдельным программам страховщика','conditional','страховщик вправе формировать условия и присваивать договорам обозначения программ','п. 1.6 – 1.6.1')
) as v(sc, sp, vd, ct, cl);

-- ── 003_Правила ДМС граждан (ред. 31.01.2023) ──
with d as (select id, insurance_company_id from program_document where storage_path='programs/sogaz_003_dms_grazhdan_2023.pdf')
insert into coverage_rule (document_id, insurance_company_id, program_name, service_class, service_pattern, verdict, condition_text, limit_amount, clause, scope_level, overridable)
select d.id, d.insurance_company_id, null, v.sc, v.sp, v.vd, v.ct, null, v.cl, 'insurer', false
from d cross join (values
('общие-условия','страховой случай обращение в медорганизацию по программе','conditional','обращение застрахованного в организацию из числа предусмотренных договором за услугами программы страхования','п. 3.1'),
('общие-условия','перечень услуг вне покрытия определяется договором','conditional','перечень услуг и заболеваний вне покрытия указывается в договоре страхования','п. 3.4 – 3.5'),
('общие-исключения','опьянение наркотические психотропные препараты без назначения врача','excluded',null,'п. 3.9'),
('общие-исключения','умышленные противоправные действия','excluded',null,'п. 3.9'),
('общие-исключения','покушение на самоубийство умышленное причинение себе вреда','excluded','кроме доведения противоправными действиями третьих лиц','п. 3.9'),
('общие-исключения','заболевания представляющие опасность для окружающих','excluded','перечень утверждается Правительством и Минздравом РФ','п. 3.9'),
('общие-условия','исключения могут быть сняты договором','conditional','договором может быть предусмотрено неприменение исключений п. 3.9 полностью или частично','п. 3.10'),
('лекарства','лекарственная помощь','conditional','если предусмотрена программой страхования','п. 3.4.2 – 3.4.3'),
('общие-условия','изменение положений правил договором','conditional','стороны вправе договориться об изменении, дополнении или исключении отдельных положений Правил','п. 12'),
('общие-условия','услуги за пределами территории страхования','excluded','кроме случаев, предусмотренных законодательством и договором','Раздел «территория страхования»')
) as v(sc, sp, vd, ct, cl);

select left(pd.title,50) || ' | правил: ' || (select count(*) from coverage_rule cr where cr.document_id=pd.id)
from program_document pd where pd.superseded_by_id is null
  and pd.insurance_company_id = (select id from insurance_company where name ilike '%СОГАЗ%');
select 'всего правил: ' || count(*) from coverage_rule;
commit;
